package com.example.editor.remote.git;

import java.time.Duration;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/** Límites del adaptador Git nativo; no introduce dependencias Java adicionales. */
@Component
@ConfigurationProperties(prefix="hydra.native-git")
public class NativeGitProperties {
    private boolean enabled=true;
    private String executable="git";
    private Duration timeout=Duration.ofSeconds(90);
    private int maximumOutputBytes=262144;
    private int maximumBranchNodesPerGroup=32;
    private int maximumCommitsPerBranch=6;
    private long outputDrainWaitMillis=2_000L;
    private int maximumConcurrentProcesses=4;
    private int processAcquireTimeoutSeconds=5;
    private long maximumTemporaryCheckoutBytes=536870912L;
    private long processTerminationGraceMillis=500L;
    private long processTerminationForceWaitMillis=1500L;
    private int processTerminationMaximumPasses=4;
    private long processTreeObservationIntervalMillis=5L;
    private Set<String> allowedHosts=new LinkedHashSet<>(List.of("github.com","gitlab.com"));

    /** Descripción: Evalúa la condición «isEnabled» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isEnabled(){return enabled;}
    /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setEnabled». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setEnabled(boolean value){enabled=value;}
    /** Descripción: Obtiene la información correspondiente a «getExecutable» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public String getExecutable(){return executable;}
    /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setExecutable». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setExecutable(String value){executable=value==null||value.isBlank()?"git":value.trim();}
    /** Descripción: Obtiene la información correspondiente a «getTimeout» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public Duration getTimeout(){return timeout;}
    /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setTimeout». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setTimeout(Duration value){timeout=value==null?Duration.ofSeconds(90):value;}
    /** Descripción: Obtiene la información correspondiente a «getMaximumOutputBytes» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumOutputBytes(){return maximumOutputBytes;}
    /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setMaximumOutputBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumOutputBytes(int value){maximumOutputBytes=Math.max(4096,value);}
    /** Descripción: Obtiene el máximo configurable de ramas que la vista del repositorio materializa por grupo. Entradas: no requiere parámetros de entrada. Salida: devuelve el límite de ramas locales o remotas mostradas en una sola consulta. */ public int getMaximumBranchNodesPerGroup(){return maximumBranchNodesPerGroup;}
    /** Descripción: Configura el máximo de ramas materializadas por grupo para mantener acotado el número de procesos Git y el tamaño de la respuesta. Entradas: value: límite solicitado. Salida: no devuelve valor; aplica un rango seguro entre 1 y 256 ramas. */ public void setMaximumBranchNodesPerGroup(int value){maximumBranchNodesPerGroup=Math.max(1,Math.min(256,value));}
    /** Descripción: Obtiene el número máximo de commits recientes materializados por rama. Entradas: no requiere parámetros de entrada. Salida: devuelve el límite de commits de la vista. */ public int getMaximumCommitsPerBranch(){return maximumCommitsPerBranch;}
    /** Descripción: Configura el número máximo de commits recientes por rama para acotar coste y volumen sin eliminar la navegación básica. Entradas: value: límite solicitado. Salida: no devuelve valor; aplica un rango seguro entre 1 y 50 commits. */ public void setMaximumCommitsPerBranch(int value){maximumCommitsPerBranch=Math.max(1,Math.min(50,value));}
    /** Espera máxima para drenar la salida del proceso Git después de su finalización. */ /** Descripción: Obtiene la información correspondiente a «getOutputDrainWaitMillis» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getOutputDrainWaitMillis(){return outputDrainWaitMillis;}
    /** Configura una espera acotada para que el lector de salida Git termine. */ /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setOutputDrainWaitMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setOutputDrainWaitMillis(long value){outputDrainWaitMillis=Math.max(100L,Math.min(30_000L,value));}
    /** Máximo de procesos Git nativos simultáneos. */ /** Descripción: Obtiene la información correspondiente a «getMaximumConcurrentProcesses» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumConcurrentProcesses(){return maximumConcurrentProcesses;}
    /** Configura el máximo de procesos Git nativos simultáneos. */ /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setMaximumConcurrentProcesses». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumConcurrentProcesses(int value){maximumConcurrentProcesses=Math.max(1,Math.min(128,value));}
    /** Tiempo máximo para adquirir capacidad de ejecución Git. */ /** Descripción: Obtiene la información correspondiente a «getProcessAcquireTimeoutSeconds» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getProcessAcquireTimeoutSeconds(){return processAcquireTimeoutSeconds;}
    /** Configura la espera por capacidad Git. */ /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setProcessAcquireTimeoutSeconds». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessAcquireTimeoutSeconds(int value){processAcquireTimeoutSeconds=Math.max(1,Math.min(300,value));}
    /** Descripción: Obtiene la información correspondiente a «getMaximumTemporaryCheckoutBytes» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaximumTemporaryCheckoutBytes(){return maximumTemporaryCheckoutBytes;}
    /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setMaximumTemporaryCheckoutBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumTemporaryCheckoutBytes(long value){maximumTemporaryCheckoutBytes=Math.max(1048576L,value);}
    /** Tiempo de gracia para terminar el árbol Git. */ /** Descripción: Obtiene la información correspondiente a «getProcessTerminationGraceMillis» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getProcessTerminationGraceMillis(){return processTerminationGraceMillis;}
    /** Configura el tiempo de gracia para terminar el árbol Git. */ /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setProcessTerminationGraceMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTerminationGraceMillis(long value){processTerminationGraceMillis=Math.max(0L,Math.min(30_000L,value));}
    /** Espera posterior a la terminación forzada de Git. */ /** Descripción: Obtiene la información correspondiente a «getProcessTerminationForceWaitMillis» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getProcessTerminationForceWaitMillis(){return processTerminationForceWaitMillis;}
    /** Configura la espera posterior a la terminación forzada de Git. */ /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setProcessTerminationForceWaitMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTerminationForceWaitMillis(long value){processTerminationForceWaitMillis=Math.max(0L,Math.min(30_000L,value));}
    /** Reescaneos máximos del árbol Git. */ /** Descripción: Obtiene la información correspondiente a «getProcessTerminationMaximumPasses» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getProcessTerminationMaximumPasses(){return processTerminationMaximumPasses;}
    /** Configura los reescaneos máximos del árbol Git. */ /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setProcessTerminationMaximumPasses». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTerminationMaximumPasses(int value){processTerminationMaximumPasses=Math.max(1,Math.min(16,value));}
    /** Intervalo de observación para conservar descendientes Git aunque la raíz termine. */ /** Descripción: Obtiene la información correspondiente a «getProcessTreeObservationIntervalMillis» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getProcessTreeObservationIntervalMillis(){return processTreeObservationIntervalMillis;}
    /** Configura el intervalo de observación del árbol Git. */ /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setProcessTreeObservationIntervalMillis». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setProcessTreeObservationIntervalMillis(long value){processTreeObservationIntervalMillis=Math.max(1L,Math.min(1_000L,value));}
    /** Descripción: Obtiene la información correspondiente a «getAllowedHosts» dentro de NativeGitProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public Set<String> getAllowedHosts(){return Set.copyOf(allowedHosts);}
    /** Descripción: Actualiza el estado gestionado por NativeGitProperties mediante la operación «setAllowedHosts». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setAllowedHosts(Set<String> value){allowedHosts=value==null?new LinkedHashSet<>():new LinkedHashSet<>(value.stream().filter(item->item!=null&&!item.isBlank()).map(String::trim).map(String::toLowerCase).toList());}
}
